import React from 'react';
import {
  ArrowUpRight,
  Briefcase,
  Building2,
  CalendarDays,
  FileBarChart2,
  FileText,
  Hand,
  LayoutDashboard,
  LogOut,
  MessageCircle,
  Settings,
  ShieldCheck,
  Users,
  UserCircle,
  UserPlus,
  FolderCog,
} from 'lucide-react';

const Sidebar = ({ isOpen, isCollapsed, onClose, onToggleCollapse, canApprove, onOpenChat, onNavigate, activeSection, currentUser }) => {
  const role = currentUser?.role || 'employee';
  const isManager = role === 'manager';
  const isHr = role === 'hr_admin';
  const isSuperAdmin = isHr && currentUser?.is_superuser === true;
  const dashboardPath = isSuperAdmin ? '/admin' : isHr ? '/hr' : isManager ? '/manager' : '/dashboard';

  const mainItems = [
    { label: 'Dashboard', icon: LayoutDashboard, section: 'dashboard', path: dashboardPath, badge: null },
    { label: 'Apply Leave', icon: CalendarDays, section: 'apply-leave', path: '/leave/apply', badge: null },
    { label: 'My Leave', icon: FileText, section: 'my-leave', path: '/leave/my', badge: null },
    { label: 'History', icon: FileBarChart2, section: 'history', path: '/leave/history', badge: null },
    { label: 'Delegations', icon: Hand, section: 'delegations', path: '/delegations', badge: currentUser?.delegation_count || null },
    { label: 'Chat', icon: MessageCircle, section: 'chat', path: '/chat', badge: currentUser?.unread_chat_count || null },
  ];

  const teamItems = [
    { label: 'Approvals', icon: ShieldCheck, section: 'approvals', path: `${isSuperAdmin ? '/admin' : isHr ? '/hr' : '/manager'}/approvals`, badge: currentUser?.pending_approval_count || null },
    { label: 'Team Calendar', icon: CalendarDays, section: 'team-calendar', path: `${isSuperAdmin ? '/admin' : isHr ? '/hr' : '/manager'}/calendar`, badge: null },
    { label: 'Reports', icon: ArrowUpRight, section: 'reports', path: `${isSuperAdmin ? '/admin' : isHr ? '/hr' : '/manager'}/reports`, badge: null },
  ];

  const hrItems = [
    { label: 'HR Verification', icon: ShieldCheck, section: 'hr-verification', path: `${isSuperAdmin ? '/admin' : '/hr'}/verification`, badge: currentUser?.hr_verification_count || null },
    { label: 'Compliance', icon: ShieldCheck, section: 'compliance', path: `${isSuperAdmin ? '/admin' : '/hr'}/compliance`, badge: currentUser?.compliance_count || null },
    { label: 'Users', icon: Users, section: 'users', path: `${isSuperAdmin ? '/admin' : '/hr'}/users`, badge: null },
    { label: 'Leave Types', icon: Briefcase, section: 'leave-types', path: `${isSuperAdmin ? '/admin' : '/hr'}/leave-types`, badge: null },
    { label: 'Departments', icon: Building2, section: 'departments', path: `${isSuperAdmin ? '/admin' : '/hr'}/departments`, badge: null },
    { label: 'Audit Log', icon: FileText, section: 'audit-log', path: `${isSuperAdmin ? '/admin' : '/hr'}/audit`, badge: null },
  ];

  const adminItems = [
    { label: 'Workflow Config', icon: Settings, section: 'workflow', path: '/admin/workflow', badge: null },
    { label: 'Pending Invites', icon: UserPlus, section: 'invites', path: '/admin/invites', badge: currentUser?.pending_invite_count || null },
    { label: 'Sessions', icon: Users, section: 'sessions', path: '/admin/sessions', badge: currentUser?.active_session_count || null },
    { label: 'Security Events', icon: ShieldCheck, section: 'security', path: '/admin/security', badge: null },
    { label: 'System Health', icon: FolderCog, section: 'system-health', path: '/admin/health', badge: null },
  ];

  const accountItems = [
    { label: 'Profile', icon: UserCircle, section: 'profile', path: '/profile', badge: null },
    { label: 'Settings', icon: Settings, section: 'settings', path: '/settings', badge: null },
    { label: 'Sign out', icon: LogOut, section: 'logout', path: '/logout', badge: null },
  ];

  const renderMenu = (items) => items.map(({ label, icon: Icon, section, badge }) => (
    <button
      key={section}
      className={`sidebar-link ${activeSection === section ? 'active' : ''}`}
      aria-current={activeSection === section ? 'page' : undefined}
      data-section={section}
      type="button"
      onClick={() => {
        if (section === 'chat' && typeof onOpenChat === 'function') onOpenChat();
        if (typeof onNavigate === 'function') onNavigate(section, items.find((item) => item.section === section)?.path);
        onClose && onClose();
      }}
    >
      <Icon size={16} aria-hidden="true" />
      <span>{label}</span>
      {badge ? <span className="sidebar-badge">{badge}</span> : null}
    </button>
  ));

  return (
    <>
      <button className={`shell-backdrop ${isOpen ? 'visible' : ''}`} aria-label="Close navigation" onClick={onClose} />
      <aside className={`app-sidebar ${isOpen ? 'open' : ''} ${isCollapsed ? 'collapsed' : ''}`} aria-label="Primary navigation">
        <div className="sidebar-brand">
          <button className="sidebar-collapse-toggle" type="button" onClick={onToggleCollapse} aria-label="Toggle sidebar">
            <span>◀</span>
          </button>
          <div className="brand-mark">
            <span className="brand-word brand-word-main">OKOA</span>
            <span className="brand-word brand-word-alt">FLOAT</span>
          </div>
        </div>

        <div className="sidebar-user-card">
          <div className="avatar-mini">{(currentUser?.name || 'J').charAt(0).toUpperCase()}</div>
          {!isCollapsed && (
            <div className="user-mini-meta">
              <div className="user-mini-name">{currentUser?.name || 'John Doe'}</div>
              <span className="role-pill">{currentUser?.role || 'employee'}</span>
            </div>
          )}
        </div>

        <nav className="sidebar-nav" aria-label="Sidebar navigation">
          {!isCollapsed && <div className="nav-label">MAIN</div>}
          {renderMenu(mainItems)}

          {(isManager || isHr || isSuperAdmin || canApprove) && (
            <>
              {!isCollapsed && <div className="nav-label">TEAM</div>}
              {renderMenu(teamItems)}
            </>
          )}

          {(isHr || isSuperAdmin) && (
            <>
              {!isCollapsed && <div className="nav-label">HR</div>}
              {renderMenu(hrItems)}
            </>
          )}

          {isSuperAdmin && (
            <>
              {!isCollapsed && <div className="nav-label">ADMIN</div>}
              {renderMenu(adminItems)}
            </>
          )}

          {!isCollapsed && <div className="nav-label">ACCOUNT</div>}
          {renderMenu(accountItems)}
        </nav>
      </aside>
    </>
  );
};

export default Sidebar;
